import java.util.Scanner;

public class Main {
    static final int MAXN = 1000005;
    static boolean[] visited = new boolean[MAXN];

    static long fastExponentiation(long base, int exponent) {
        long result = 1;
        long mod = 1000000007;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % mod;
            }
            exponent >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(fastExponentiation(p, (int)(p - 1)));
            return;
        }
        if (k == 1) {
            System.out.println(fastExponentiation(p, (int)p));
            return;
        }

        int count = 0;
        for (int i = 1; i < p; i++) {
            if (visited[i]) continue;
            long j = i;
            while (!visited[(int)j]) {
                visited[(int)j] = true;
                j = (j * k) % p;
            }
            count++;
        }
        System.out.println(fastExponentiation(p, count));
    }
}
